    pub struct DependencyRefTypeSerializer<'ser> {
        pub(super) value: &'ser super::DependencyRefType,
        pub(super) state: Box<DependencyRefTypeSerializerState<'ser>>,
        pub(super) name: &'ser str,
        pub(super) is_root: bool,
    }
    #[derive(Debug)]
    pub(super) enum DependencyRefTypeSerializerState<'ser> {
        Init__,
        Done__,
        Phantom__(&'ser ()),
    }
    impl<'ser> DependencyRefTypeSerializer<'ser> {
        fn next_event(
            &mut self,
            helper: &mut SerializeHelper,
        ) -> Result<Option<Event<'ser>>, Error> {
            loop {
                match &mut *self.state {
                    DependencyRefTypeSerializerState::Init__ => {
                        *self.state = DependencyRefTypeSerializerState::Done__;
                        let mut bytes = BytesStart::new(self.name);
                        helper.begin_ns_scope();
                        if self.is_root {
                            helper.write_xmlns(&mut bytes, Some(&super::PREFIX_TG), &super::NS_TG);
                        }
                        helper.write_attrib(&mut bytes, "ref", &self.value.ref_)?;
                        helper.end_ns_scope();
                        return Ok(Some(Event::Empty(bytes)));
                    }
                    DependencyRefTypeSerializerState::Done__ => return Ok(None),
                    DependencyRefTypeSerializerState::Phantom__(_) => unreachable!(),
                }
            }
        }
    }
    impl<'ser> Serializer<'ser> for DependencyRefTypeSerializer<'ser> {
        fn next(&mut self, helper: &mut SerializeHelper) -> Option<Result<Event<'ser>, Error>> {
            match self.next_event(helper) {
                Ok(Some(event)) => Some(Ok(event)),
                Ok(None) => None,
                Err(error) => {
                    *self.state = DependencyRefTypeSerializerState::Done__;
                    Some(Err(error))
                }
            }
        }
    }
